BEGIN;
CREATE FUNCTION tender.tsc_question_key(value text) RETURNS text LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
 SELECT lower(regexp_replace(btrim(value), '[[:space:][:punct:]]+', '', 'g'))
$$;
CREATE TABLE tender.tsc_formats (
 id uuid PRIMARY KEY, name text NOT NULL CHECK(char_length(btrim(name)) BETWEEN 3 AND 120),
 name_key text GENERATED ALWAYS AS (tender.tsc_question_key(name)) STORED UNIQUE,
 description text NOT NULL DEFAULT '' CHECK(char_length(description)<=1000),
 is_active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1 CHECK(version>0),
 created_by_id uuid REFERENCES auth.users(id), updated_by_id uuid REFERENCES auth.users(id),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE tender.tsc_format_questions (
 format_id uuid NOT NULL REFERENCES tender.tsc_formats(id), id text NOT NULL CHECK(id ~ '^[a-zA-Z0-9_.-]{1,80}$'),
 position integer NOT NULL CHECK(position BETWEEN 1 AND 200),
 section text NOT NULL CHECK(char_length(btrim(section)) BETWEEN 1 AND 80),
 printed_number text NOT NULL CHECK(char_length(printed_number)<=30),
 question text NOT NULL CHECK(char_length(btrim(question)) BETWEEN 3 AND 2000),
 question_key text GENERATED ALWAYS AS (tender.tsc_question_key(question)) STORED,
 manual_review boolean NOT NULL DEFAULT false, legacy_row integer NOT NULL DEFAULT 0,
 PRIMARY KEY(format_id,id), UNIQUE(format_id,position), UNIQUE(format_id,question_key)
);
CREATE TABLE tender.tsc_format_events (
 id uuid PRIMARY KEY, format_id uuid NOT NULL REFERENCES tender.tsc_formats(id), version bigint NOT NULL,
 actor_id uuid NOT NULL REFERENCES auth.users(id), before_snapshot jsonb, after_snapshot jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(format_id,version)
);
CREATE TRIGGER tsc_format_events_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON tender.tsc_format_events
 FOR EACH STATEMENT EXECUTE FUNCTION public.epcerp_reject_event_mutation();
