ALTER TABLE tender.tsc_jobs ADD COLUMN format_id uuid REFERENCES tender.tsc_formats(id), ADD COLUMN format_version bigint;
ALTER TABLE tender.tsc_jobs ADD CONSTRAINT tsc_job_format_pair CHECK((format_id IS NULL)=(format_version IS NULL) AND (format_version IS NULL OR format_version>0));
CREATE FUNCTION tender.protect_tsc_format_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF ROW(NEW.format_id,NEW.format_version) IS DISTINCT FROM ROW(OLD.format_id,OLD.format_version) THEN RAISE EXCEPTION 'TSC format snapshot is immutable'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER tsc_format_snapshot_immutable BEFORE UPDATE ON tender.tsc_jobs FOR EACH ROW EXECUTE FUNCTION tender.protect_tsc_format_snapshot();
COMMIT;
